#include <bits/stdc++.h>
using namespace std;

int fmod = 998244353;
vector<long long> fact, ifact;

long long fmul(long long a, long long b) {
    return (a * b) % fmod;
}

long long fpow(long long a, long long b) {
    long long result = 1;
    long long base = a % fmod;
    long long exp = b;
    while (exp > 0) {
        if (exp & 1) {
            result = fmul(result, base);
        }
        base = fmul(base, base);
        exp >>= 1;
    }
    return result;
}

long long ifact_func(int x) {
    static vector<long long> ifact_cache;
    static bool initialized = false;
    if (!initialized) {
        ifact_cache.resize(100000 + 1, -1);
        initialized = true;
    }
    if (x < (int)ifact_cache.size() && ifact_cache[x] != -1) {
        return ifact_cache[x];
    } else {
        long long res = fpow(fact[x], fmod - 2);
        if (x < (int)ifact_cache.size()) {
            ifact_cache[x] = res;
        }
        return res;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long kl;
    cin >> n >> kl;
    if (kl >= n) {
        cout << 0 << "\n";
        return 0;
    }
    int k = (int)kl;
    fact.resize(n + 1);
    ifact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fmul(fact[i - 1], i);
    }
    long long ans = 0;
    for (int i = 0; i <= n - k; i++) {
        int sign = (i % 2 == 0) ? 1 : -1;
        long long term = fmul(sign, fmul(fpow(n - k - i, n), fmul(fact[n - k], fmul(ifact_func(i), ifact_func(n - k - i)))));
        term %= fmod;
        if (term < 0) term += fmod;
        ans += term;
        ans %= fmod;
    }
    long long res = fmul(fmul(ans, fact[n]), fmul(ifact_func(k), ifact_func(n - k)));
    if (k == 0) {
        cout << res % fmod << "\n";
    } else {
        cout << fmul(res, 2) % fmod << "\n";
    }
    return 0;
}
